package dev.pathland.markdown;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import dev.pathland.view.core.AttributedString;
import dev.pathland.view.core.LinkRun;
import dev.pathland.view.core.StyleRun;
import dev.pathland.view.core.protocol.Properties;
import org.junit.jupiter.api.Test;

/**
 * The pure-Java parser must match the Rust {@code pathland-markdown} parser
 * exactly (the Rust test suite is mirrored here, including UTF-8 byte offsets).
 */
class MarkdownTest {

    private static AttributedString decoded(String markdown) {
        return Markdown.parse(markdown);
    }

    private static boolean hasProperty(StyleRun run, int property) {
        return run.getAttributes().stream().anyMatch(a -> a.getProperty() == property);
    }

    private static int valueOf(StyleRun run, int property) {
        return run.getAttributes().stream()
                .filter(a -> a.getProperty() == property)
                .findFirst()
                .orElseThrow()
                .getValue();
    }

    @Test
    void isAlwaysAvailable() {
        assertTrue(Markdown.isAvailable());
    }

    @Test
    void plainTextHasNoRuns() {
        AttributedString value = decoded("hello");
        assertEquals("hello", value.getText());
        assertTrue(value.getRuns().isEmpty());
        assertTrue(value.getLinks().isEmpty());
    }

    @Test
    void mapsEachInlineMarker() {
        AttributedString value = decoded("**b** *i* `c` ~~s~~");
        assertEquals("b i c s", value.getText());
        assertEquals(4, value.getRuns().size());

        StyleRun bold = value.getRuns().get(0);
        assertEquals(0, bold.getStart());
        assertEquals(1, bold.getEnd());
        assertEquals(Float.floatToRawIntBits(700.0f), valueOf(bold, Properties.FONT_WEIGHT));

        StyleRun italic = value.getRuns().get(1);
        assertEquals(2, italic.getStart());
        assertEquals(3, italic.getEnd());
        assertEquals(Float.floatToRawIntBits(1.0f), valueOf(italic, Properties.FONT_STYLE));

        StyleRun code = value.getRuns().get(2);
        assertEquals(4, code.getStart());
        assertEquals(5, code.getEnd());
        assertEquals(Float.floatToRawIntBits(3.0f), valueOf(code, Properties.FONT_DESIGN));

        StyleRun strike = value.getRuns().get(3);
        assertEquals(6, strike.getStart());
        assertEquals(7, strike.getEnd());
        assertTrue(hasProperty(strike, Properties.STRIKETHROUGH));
    }

    @Test
    void nestsFormats() {
        AttributedString value = decoded("**bold *and italic***");
        assertEquals("bold and italic", value.getText());
        assertEquals(2, value.getRuns().size());
        assertEquals(5, value.getRuns().get(0).getStart());
        assertEquals(15, value.getRuns().get(0).getEnd());
        assertEquals(0, value.getRuns().get(1).getStart());
        assertEquals(15, value.getRuns().get(1).getEnd());
    }

    @Test
    void linksCarryLabelRunsAndUrl() {
        AttributedString value = decoded("[**hi**](https://example.com)");
        assertEquals("hi", value.getText());
        assertEquals(1, value.getLinks().size());
        LinkRun link = value.getLinks().get(0);
        assertEquals("https://example.com", link.getUrl());
        assertEquals(0, link.getStart());
        assertEquals(2, link.getEnd());
        assertEquals(1, value.getRuns().size());
    }

    @Test
    void codeSpansDoNotParseInnerMarkup() {
        AttributedString value = decoded("`**not bold**`");
        assertEquals("**not bold**", value.getText());
        assertEquals(1, value.getRuns().size());
        assertTrue(hasProperty(value.getRuns().get(0), Properties.FONT_DESIGN));
    }

    @Test
    void underscoreEmphasisMatchesAsteriskForms() {
        AttributedString value = decoded("_italic_ and __bold__");
        assertEquals("italic and bold", value.getText());
        assertEquals(2, value.getRuns().size());
        assertTrue(hasProperty(value.getRuns().get(0), Properties.FONT_STYLE));
        assertTrue(hasProperty(value.getRuns().get(1), Properties.FONT_WEIGHT));
    }

    @Test
    void intrawordUnderscoresStayLiteral() {
        AttributedString value = decoded("snake_case_name");
        assertEquals("snake_case_name", value.getText());
        assertTrue(value.getRuns().isEmpty());
    }

    @Test
    void escapedUnderscoresAreLiteral() {
        AttributedString value = decoded("\\_not italic\\_");
        assertEquals("_not italic_", value.getText());
        assertTrue(value.getRuns().isEmpty());
    }

    @Test
    void escapesAreLiteral() {
        AttributedString value = decoded("\\*not italic\\*");
        assertEquals("*not italic*", value.getText());
        assertTrue(value.getRuns().isEmpty());
    }

    @Test
    void unmatchedMarkersStayLiteral() {
        AttributedString value = decoded("a * b ** c");
        assertEquals("a * b ** c", value.getText());
        assertTrue(value.getRuns().isEmpty());
    }

    @Test
    void utf8OffsetsAreBytes() {
        AttributedString value = decoded("\u00e9**\u00fc**");
        assertEquals("\u00e9\u00fc", value.getText());
        assertEquals(2, value.getRuns().get(0).getStart());
        assertEquals(4, value.getRuns().get(0).getEnd());
    }

    @Test
    void roundTripsThroughTheWirePayload() {
        AttributedString value = Markdown.parse("`code`");
        AttributedString decoded = AttributedString.decode(value.encode());
        assertEquals("code", decoded.getText());
        assertTrue(hasProperty(decoded.getRuns().get(0), Properties.FONT_DESIGN));
    }

    @Test
    void parseOrPlainSkipsPlainText() {
        assertTrue(Markdown.containsMarkdownSyntax("**hi**"));
        assertFalse(Markdown.containsMarkdownSyntax("plain text"));
        AttributedString plain = Markdown.parseOrPlain("plain text");
        assertEquals("plain text", plain.getText());
        assertTrue(plain.getRuns().isEmpty());
        AttributedString rich = Markdown.parseOrPlain("**hi**");
        assertFalse(rich.getRuns().isEmpty());
    }
}

    /// Follow the platform's native light/dark signal (default).
    pub const PLATFORM: u32 = 0;
    /// Force the light scheme.
    pub const LIGHT: u32 = 1;
    /// Force the dark scheme.
    pub const DARK: u32 = 2;
}

/// Environment field ids for `META::ENVIRONMENT` (host → guest).
///
/// Each opcode sets one platform environment field; new fields are new ids, never
/// new commands (spec/OPCODE.md §Environment fields).
pub mod environment {
    /// Viewport width in logical points (f32 in `B`).
    pub const VIEWPORT_WIDTH: u16 = 0x0001;
    /// Viewport height in logical points (f32 in `B`).
    pub const VIEWPORT_HEIGHT: u16 = 0x0002;
    /// The initial route/deep-link path (STRING: `B` is a string-section/event-arena
    /// offset — the `TEXT_CHANGED`/`NAVIGATE` dual convention).
    pub const ROUTE: u16 = 0x0003;
}

/// Flag bits used across categories.
pub mod flag {
    /// `POINTER_DOWN` / `POINTER_UP`: secondary button (bit 0).
    pub const POINTER_SECONDARY: u16 = 0x0001;
    /// `POINTER_MOVE`: pointer is entering/hovering (bit 0).
    pub const HOVER_ENTER: u16 = 0x0001;
    /// `POINTER_MOVE`: pointer is leaving (bit 1).
    pub const HOVER_LEAVE: u16 = 0x0002;
    /// `KEY_DOWN`: key repeat (bit 1).
    pub const KEY_REPEAT: u16 = 0x0002;
    /// `NAVIGATE`: `B` is a URL string offset (bit 0). Without this flag the
    /// event is a back request.
    pub const NAVIGATE_URL: u16 = 0x0001;
}

/// Bits for the `EVENT_LISTENERS` semantic property (a u32 bitmask).
///
/// Each bit requests that a renderer attach native input recognition for the
/// matching raw-input event and report it for that node — so any element (not
/// just a button) can emit raw events. Bits are independent of the `EVENT`
/// command ids; more event kinds can be added later.
pub mod listener {
    /// `POINTER_DOWN` events (bit 0).
    pub const POINTER_DOWN: u32 = 1 << 0;
    /// `POINTER_MOVE` events (bit 1).
    pub const POINTER_MOVE: u32 = 1 << 1;
    /// `POINTER_UP` events (bit 2).
    pub const POINTER_UP: u32 = 1 << 2;
    /// `KEY_DOWN` events (bit 3).
    pub const KEY_DOWN: u32 = 1 << 3;
    /// `KEY_UP` events (bit 4).
    pub const KEY_UP: u32 = 1 << 4;
    /// **Draft.** `FOCUS_CHANGED` events (bit 5).
    pub const FOCUS: u32 = 1 << 5;
    /// **Draft.** `EDITING_CHANGED` events (bit 6).
    pub const EDITING: u32 = 1 << 6;
    /// **Draft.** `SUBMIT` events (bit 7).
    pub const SUBMIT: u32 = 1 << 7;
    /// **Draft.** `SCROLL` events (bit 8).
    pub const SCROLL: u32 = 1 << 8;
    /// **Draft.** `WHEEL` events (bit 9).
    pub const WHEEL: u32 = 1 << 9;

    /// All pointer events (down + move + up).
    pub const POINTER: u32 = POINTER_DOWN | POINTER_MOVE | POINTER_UP;
}

/// Bits for the `BORDER_EDGES` style property (a u32 bitmask).
///
/// Each bit selects one edge of a node's border. `LEADING`/`TRAILING` are
/// direction-aware; a renderer resolves them to physical `left`/`right`
/// according to its layout direction (LTR by default).
pub mod border_edges {
    /// Top edge (bit 0).
    pub const TOP: u32 = 1 << 0;
    /// Leading edge (bit 1) — physical left in LTR.
    pub const LEADING: u32 = 1 << 1;
    /// Bottom edge (bit 2).
    pub const BOTTOM: u32 = 1 << 2;
    /// Trailing edge (bit 3) — physical right in LTR.
    pub const TRAILING: u32 = 1 << 3;

    /// All four edges.
    pub const ALL: u32 = TOP | LEADING | BOTTOM | TRAILING;
}

/// Value types for `PARAMETER` properties (u8, encoded in the high byte of `B`).
pub mod value_type {
    pub const U8: u8 = 0x01;
    pub const U32: u8 = 0x02;
    pub const I32: u8 = 0x03;
    pub const F32: u8 = 0x04;
    pub const STRING: u8 = 0x05;
    pub const ENUM: u8 = 0x06;
    pub const COLOR: u8 = 0x07;
    pub const DESIGN_TOKEN: u8 = 0x08;
    /// **Draft.** Arena-backed length-prefixed array: `[u32 count][element × count]`
    /// in the string arena (each element holds the value-type's bit pattern —
    /// today `F32`s, e.g. the `FIT_QUERY` threshold table).
    pub const LIST: u8 = 0x09;
}

/// Component types (u16, encoded in the low half of `B` of `TREE::CREATE_NODE`).
///
/// IDs are grouped into three definitive ranges (see `spec/PRIMITIVES.md`):
/// Primitive Drawing `0x01`–`0x0F`, Layout & Container `0x10`–`0x1F`, Semantic
/// Control `0x20`–`0x2F`, plus the utility `COMMENT` at `0x7F`. Renumbered
/// pre-release (wire version stays 1).
pub mod component_type {
    // ── Primitive Drawing & Visual Nodes (0x01–0x0F) ────────────────────────
    /// Standard styled text display.
    pub const TEXT: u16 = 0x01;
    /// Raster, vector, or system icon asset.
    pub const IMAGE: u16 = 0x02;
    /// **Draft.** Solid color / layout-filling background view.
    pub const COLOR: u16 = 0x03;
    /// **Draft.** Vector geometry (`SHAPE_KIND` selects the shape).
    pub const SHAPE: u16 = 0x04;
    /// **Draft.** Axis-aligned separator line.
    pub const DIVIDER: u16 = 0x05;
    /// Flexible expanding layout filler.
    pub const SPACER: u16 = 0x06;
    /// **Draft.** Determinate progress or activity indicator.
    pub const PROGRESS_VIEW: u16 = 0x07;
    /// **Draft.** Range meter against a scale (read-only).
    pub const GAUGE: u16 = 0x08;
    // 0x09 freed (formerly AUDIO — audio now has no view; see MEDIA_CONTROLLER).
    /// **Draft.** Video playback **surface** — renders a `MEDIA_CONTROLLER`'s
    /// video output; it references the controller via `MEDIA_CONTROLLER_ID` and
    /// carries no source of its own (spec/MEDIA.md).
    pub const VIDEO: u16 = 0x0A;
    /// **Draft.** Semantic icon (`ICON_NAME` selects a renderer-native symbol —
    /// Adwaita on GTK, Lucide on the web; spec/ICONS.md).
    pub const ICON: u16 = 0x0B;
    // 0x0C–0x0F reserved (future drawing nodes).

    // ── Layout & Container Primitives (0x10–0x1F) ───────────────────────────
    /// Vertical flex stack.
    pub const VSTACK: u16 = 0x10;
    /// Horizontal flex stack.
    pub const HSTACK: u16 = 0x11;
    /// **Draft.** Depth-overlapping layer stack.
    pub const ZSTACK: u16 = 0x12;
    /// Static 2D matrix grid (eagerly rendered).
    pub const GRID: u16 = 0x13;
    /// Scrollable content container.
    pub const SCROLLVIEW: u16 = 0x14;
    /// **Draft.** Virtualized vertical grid.
    pub const LAZY_VGRID: u16 = 0x15;
    /// **Draft.** Virtualized horizontal grid.
    pub const LAZY_HGRID: u16 = 0x16;
    /// **Draft.** Fit slot (`SizeThatFits`): shows its single selected child —
    /// only the selected candidate is ever transmitted. The renderer measures
    /// its own allocated width against `FIT_QUERY` and reports `FIT_CHANGED`.
    pub const SIZE_THAT_FITS: u16 = 0x17;
    // 0x18–0x1A reserved (formerly composite views, removed).
    /// **Draft.** Virtualized vertical stack.
    pub const LAZY_VSTACK: u16 = 0x1B;
    /// **Draft.** Virtualized horizontal stack.
    pub const LAZY_HSTACK: u16 = 0x1C;
    /// **Draft.** Explicit row grouping for a `GRID`: a grid child whose children
    /// are one row's cells (the SwiftUI `GridRow` surface). Renders nothing
    /// outside a `GRID`.
    pub const GRID_ROW: u16 = 0x1D;
    /// **Draft.** Proxy view (`spec/PROXY.md`): a transparent single-child
    /// container whose child subtree is served by **another** Pathland server.
    /// Renderers render it as a plain container; the proxying server remaps the
    /// foreign subtree's node ids into a disjoint high range and routes its
    /// events back to the origin server.
    pub const PROXY_VIEW: u16 = 0x1E;
    // 0x1F reserved (future layout nodes).

    // ── Semantic Control Nodes (0x20–0x2F) ──────────────────────────────────
    /// Action trigger control.
    pub const BUTTON: u16 = 0x20;
    /// Single-line text input (secure variant via `IS_SECURE`).
    pub const TEXT_FIELD: u16 = 0x21;
    /// **Draft.** Multi-line text editing area.
    pub const TEXT_EDITOR: u16 = 0x22;
    // 0x23 reserved.
    /// Boolean control; the visual variant is `TOGGLE_STYLE`
    /// (`Switch`/`Checkbox`/`Button`).
    pub const TOGGLE: u16 = 0x24;
    /// Continuous or stepped numeric range control.
    pub const SLIDER: u16 = 0x25;
    /// **Draft.** Discrete increment/decrement control.
    pub const STEPPER: u16 = 0x26;
    /// **Draft.** Date & time selection control (`PARAMETER::SET_DATE` value).
    pub const DATE_PICKER: u16 = 0x27;
    /// **Draft.** Selection control (options are child nodes).
    pub const PICKER: u16 = 0x28;
    /// **Draft.** Contextual action trigger + popover container.
    pub const MENU: u16 = 0x29;
    /// **Draft.** Native system color picker control.
    pub const COLOR_PICKER: u16 = 0x2A;
    // 0x2B–0x2F reserved (future semantic controls).

    // ── Non-visual / Resource Nodes (0x30–0x3F) ─────────────────────────────
    /// **Draft.** Media controller — a **non-visual** node that owns a media
    /// resource (`MEDIA_SOURCE`) and its transport state (`PLAYBACK_STATE`,
    /// `MEDIA_POSITION`, `MEDIA_VOLUME`, `MEDIA_MUTED`, `MEDIA_LOOP`,
    /// `MEDIA_RATE`). A `VIDEO` surface references it by id
    /// (`MEDIA_CONTROLLER_ID`); audio has no view and is controlled by the
    /// application's own views. Layout-transparent (spec/MEDIA.md).
    pub const MEDIA_CONTROLLER: u16 = 0x30;
    // 0x31–0x3F reserved (future non-visual/resource nodes).

    /// Opaque/debug node; renderers ignore it (no native element).
    pub const COMMENT: u16 = 0x7F;
}

/// Property IDs (u16, encoded in the low half of `B` of `PARAMETER::SET_PROPERTY`).
///
/// IDs are specified in `spec/OPCODE.md` (carried forward from the historical protocol).
pub mod property_id {
    // Stack
    pub const SPACING: u16 = 0x0001;
    pub const ALIGNMENT: u16 = 0x0002;
    // 0x0003 reserved (formerly JUSTIFICATION; main-axis distribution is
    // expressed via a spacer element instead).
    // 0x0004 reserved (formerly PADDING; now a styling modifier at 0x1011).
    pub const CONTENT_MARGINS: u16 = 0x0005;
    // Text
    pub const TEXT: u16 = 0x000A;
    pub const LINE_LIMIT: u16 = 0x000B;
    pub const TEXT_ALIGNMENT: u16 = 0x000C;
    pub const TRUNCATION_MODE: u16 = 0x000D;
