package dev.pathland.docs

import java.util.Locale

/** One documentation page loaded from a Markdown resource. */
data class DocsPage(
    val sourcePath: String,
    val route: String,
    val title: String,
    val description: String? = null,
    val section: String? = null,
    val order: Int = 1000,
    val draft: Boolean = false,
    val updated: String? = null,
    val image: String? = null,
    val markdown: String,
) {
    companion object {
        private val FRONT_MATTER = Regex("^\\uFEFF?---\\s*\\r?\\n(.*?)\\r?\\n---\\s*\\r?\\n?", RegexOption.DOT_MATCHES_ALL)

        /**
         * Parse one `.md` resource: YAML-ish front matter (flat `key: value`
         * entries — enough for docs metadata; no YAML dependency) plus the body.
         */
        @JvmStatic
        @JvmOverloads
        fun fromMarkdown(
            sourcePath: String,
            raw: String,
            routePrefix: String = "/docs",
        ): DocsPage {
            val match = FRONT_MATTER.find(raw)
            val fields = LinkedHashMap<String, String>()
            val body = if (match != null) {
                parseFields(match.groupValues[1], fields)
                raw.substring(match.range.last + 1)
            } else {
                raw
            }
            val fallbackTitle = firstHeading(body) ?: humanize(fileName(sourcePath))
            val route = fields["route"]?.takeIf { it.isNotBlank() } ?: deriveRoute(sourcePath, routePrefix)
            return DocsPage(
                sourcePath = sourcePath,
                route = normalizeRoute(route),
                title = fields["title"]?.takeIf { it.isNotBlank() } ?: fallbackTitle,
                description = fields["description"]?.takeIf { it.isNotBlank() } ?: firstParagraph(body),
                section = fields["section"]?.takeIf { it.isNotBlank() },
                order = fields["order"]?.trim()?.toIntOrNull() ?: 1000,
                draft = fields["draft"]?.trim()?.equals("true", ignoreCase = true) == true,
                updated = fields["updated"]?.takeIf { it.isNotBlank() },
                image = fields["image"]?.takeIf { it.isNotBlank() },
                markdown = body.trimStart('\n'),
            )
        }

        private fun parseFields(text: String, out: MutableMap<String, String>) {
            for (line in text.lineSequence()) {
                val trimmed = line.trim()
                if (trimmed.isEmpty() || trimmed.startsWith("#")) continue
                val colon = trimmed.indexOf(':')
                if (colon <= 0) continue
                val key = trimmed.substring(0, colon).trim().lowercase(Locale.ROOT)
                var value = trimmed.substring(colon + 1).trim()
                if (value.length >= 2 &&
                    ((value.startsWith("\"") && value.endsWith("\"")) ||
                        (value.startsWith("'") && value.endsWith("'")))
                ) {
                    value = value.substring(1, value.length - 1)
                }
                out[key] = value
            }
        }

        private fun fileName(path: String): String =
            path.substringAfterLast('/').substringBeforeLast('.')

        private fun firstHeading(markdown: String): String? =
            markdown.lineSequence().firstOrNull { it.trimStart().startsWith("# ") }
                ?.trimStart()?.removePrefix("# ")?.trim()?.takeIf { it.isNotEmpty() }

        private fun firstParagraph(markdown: String): String? =
            markdown.lineSequence()
                .map { it.trim() }
                .firstOrNull { it.isNotEmpty() && !it.startsWith("#") && !it.startsWith("```") }
                ?.replace(Regex("[*_`~\\[\\]]"), "")
                ?.takeIf { it.isNotEmpty() }

        private fun humanize(name: String): String =
            name.split('-', '_')
                .filter { it.isNotBlank() }
                .joinToString(" ") { token -> token.replaceFirstChar { it.uppercaseChar() } }

        /** `docs/guides/install.md` or `content/docs/guides/index.md` → `/docs/guides/install`. */
        @JvmStatic
        @JvmOverloads
        fun deriveRoute(sourcePath: String, routePrefix: String = "/docs"): String {
            val normalized = sourcePath.replace('\\', '/')
            var path = normalized
            listOf("content/docs/", "docs/", "content/").forEach { prefix ->
                if (path.startsWith(prefix)) path = path.removePrefix(prefix)
            }
            path = path.removeSuffix(".md").removeSuffix(".markdown")
            val segments = path.split('/').filter { it.isNotBlank() }
            val clean = buildList {
                for (segment in segments) {
                    if (segment == "index" || segment == "README") {
                        if (isEmpty()) add("")
                        continue
                    }
                    add(slug(segment))
                }
            }.filter { it.isNotEmpty() }
            val suffix = clean.joinToString("/")
            return when {
                suffix.isEmpty() -> routePrefix
                else -> routePrefix.trimEnd('/') + "/" + suffix
            }
        }

        private fun slug(value: String): String =
            value.trim().lowercase(Locale.ROOT)
                .replace(Regex("[^a-z0-9]+"), "-")
                .trim('-')

        private fun normalizeRoute(value: String): String {
            val trimmed = value.trim()
            val withSlash = if (trimmed.startsWith('/')) trimmed else "/$trimmed"
            return if (withSlash.length > 1) withSlash.trimEnd('/') else withSlash
        }
    }
}

/** A navigation group (section) containing pages in display order. */
data class DocsSection(
    val title: String?,
    val pages: List<DocsPage>,
)

package dev.pathland.docs

import java.nio.charset.StandardCharsets
import java.nio.file.Files
import java.nio.file.Path
import java.util.Locale

/** The docs content set: pages, navigation, TOC and prev/next resolution. */
class DocsRepository(
    pages: List<DocsPage>,
    private val routePrefix: String = "/docs",
) {
    val pages: List<DocsPage> = pages
        .filterNot { it.draft }
        .sortedWith(compareBy<DocsPage>({ it.section ?: "" }, { it.order }, { it.title }))

    private val byRoute: Map<String, DocsPage> = buildMap {
        for (page in this@DocsRepository.pages) {
            require(!containsKey(page.route)) { "duplicate docs route: ${page.route}" }
            put(page.route, page)
        }
    }

    init {
        require(this.pages.isNotEmpty()) { "docs repository is empty" }
    }

    fun page(route: String): DocsPage? = byRoute[normalize(route)]

    fun sections(): List<DocsSection> =
        pages.groupBy { it.section }.map { (section, pages) -> DocsSection(section, pages) }

    fun toc(page: DocsPage): List<MarkdownHeading> = MarkdownHeadings.extract(page.markdown)

    fun previous(page: DocsPage): DocsPage? {
        val index = pages.indexOfFirst { it.route == page.route }
        return if (index > 0) pages[index - 1] else null
    }

    fun next(page: DocsPage): DocsPage? {
        val index = pages.indexOfFirst { it.route == page.route }
        return if (index >= 0 && index + 1 < pages.size) pages[index + 1] else null
    }

    fun routes(): List<String> = pages.map { it.route }

    private fun normalize(route: String): String {
        val path = route.substringBefore('?').substringBefore('#')
        val withSlash = if (path.startsWith('/')) path else "/$path"
        return if (withSlash.length > 1) withSlash.trimEnd('/') else withSlash
    }

    companion object {
        /** Read the `.md` resources named by a classpath index (one path per line). */
        @JvmStatic
        @JvmOverloads
        fun fromResources(
            indexResource: String = "META-INF/pathland-docs.index",
            routePrefix: String = "/docs",
            classLoader: ClassLoader = Thread.currentThread().contextClassLoader
                ?: DocsRepository::class.java.classLoader,
        ): DocsRepository {
            val index = classLoader.getResourceAsStream(indexResource)
                ?: error("missing docs index resource: $indexResource")
            val paths = index.bufferedReader(StandardCharsets.UTF_8).useLines { lines ->
                lines.map { it.trim() }
                    .filter { it.isNotEmpty() && !it.startsWith("#") }
                    .toList()
            }
            val pages = paths.map { path ->
                val stream = classLoader.getResourceAsStream(path)
                    ?: error("missing docs resource: $path")
                val raw = stream.bufferedReader(StandardCharsets.UTF_8).use { it.readText() }
                DocsPage.fromMarkdown(path, raw, routePrefix)
            }
            return DocsRepository(pages, routePrefix)
        }

        /** Read a filesystem directory (dev mode / tests). */
        @JvmStatic
        @JvmOverloads
        fun fromDirectory(
            directory: Path,
            routePrefix: String = "/docs",
        ): DocsRepository {
            require(Files.isDirectory(directory)) { "docs directory not found: $directory" }
            val pages = Files.walk(directory).use { paths ->
                paths.filter { Files.isRegularFile(it) && it.fileName.toString().endsWith(".md") }
                    .sorted()
                    .map { file ->
                        val relative = directory.relativize(file).toString().replace('\\', '/')
                        DocsPage.fromMarkdown(
                            sourcePath = relative,
                            raw = Files.readString(file, StandardCharsets.UTF_8),
                            routePrefix = routePrefix,
                        )
                    }
                    .toList()
            }
            return DocsRepository(pages, routePrefix)
        }

        /** Build a repository from explicit Markdown strings (tests / small sites). */
        @JvmStatic
        @JvmOverloads
        fun fromMarkdown(
            entries: Map<String, String>,
            routePrefix: String = "/docs",
        ): DocsRepository = DocsRepository(
            entries.map { (path, raw) -> DocsPage.fromMarkdown(path, raw, routePrefix) },
            routePrefix,
        )
    }
}

/** A heading extracted for a table of contents. */
data class MarkdownHeading(
    val level: Int,
    val id: String,
    val text: String,
)

/** Heading extraction + slugging (the same rules the block renderer uses). */
object MarkdownHeadings {
    private val ATX = Regex("^\\s{0,3}(#{1,6})\\s+(.*?)\\s*#*\\s*$")

    @JvmStatic
    fun extract(markdown: String): List<MarkdownHeading> {
        val headings = ArrayList<MarkdownHeading>()
        val slugger = Slugger()
        var fence = false
        for (line in markdown.lineSequence()) {
            val trimmed = line.trimStart()
            if (trimmed.startsWith("```") || trimmed.startsWith("~~~")) {
                fence = !fence
                continue
            }
            if (fence) continue
            val match = ATX.matchEntire(line) ?: continue
            val level = match.groupValues[1].length
            val text = match.groupValues[2].trim()
            if (text.isEmpty()) continue
            headings.add(MarkdownHeading(level, slugger.slug(plain(text)), plain(text)))
        }
        return headings
    }

    @JvmStatic
    fun plain(inline: String): String =
        inline.replace(Regex("!?\\[([^\\]]*)]\\([^)]*\\)"), "$1")
            .replace(Regex("[*_`~]"), "")
            .replace(Regex("\\\\([\\\\`*_{}\\[\\]()#+.!~-])"), "$1")
            .trim()
}

/** Unique, GitHub-style heading ids (`intro`, `intro-1`, …). */
class Slugger {
    private val seen = HashMap<String, Int>()

    fun slug(text: String): String {
        val base = MarkdownHeadings.plain(text)
            .lowercase(Locale.ROOT)
            .replace(Regex("[^a-z0-9\\s-]"), "")
            .trim()
            .replace(Regex("\\s+"), "-")
            .trim('-')
            .ifEmpty { "section" }
        val count = seen[base] ?: 0
        seen[base] = count + 1
        return if (count == 0) base else "$base-$count"
    }
}

